#!/usr/bin/env node
// Vendor llms.txt / llms.json into static/, rewritten for this site's domain.
//
// The monorepo's own llms.txt/llms.json (repo root, generated by
// scripts/generate-llms-files.py) are the source of truth for *what* is
// curated -- the same one list this script reads rather than re-typing.
// What changes here is *where each entry points*: the monorepo's copy links
// into the repository itself (GitHub blob URLs), which resolve from a
// checkout or from GitHub but are not this site's own pages
// (spec/llms-json-and-llms-txt/index.md, added for exactly this reason). A
// link becomes a site route when this site actually publishes that content
// -- `src/lib/paths.js`'s `routeFor`, the same translation the rendered
// pages already use for the vendored Markdown's own internal links, so
// there is one rule for "does this site publish that file", not two -- and
// stays a GitHub link otherwise, which is the same choice `paths.js` makes
// rather than a dead relative link no domain resolves.
//
// Source, overridable the same way sync-content.mjs's is:
//   $OPENEHR_RUST  else the sibling checkout ../..
//
// Run after the monorepo's llms.txt/llms.json change:  npm run sync:llms

import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { routeFor } from '../src/lib/paths.js';
import { SITE_URL, REPOSITORIES } from '../src/lib/site.js';

const siteRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const root = resolve(process.env.OPENEHR_RUST ?? join(siteRoot, '..'));

const sourcePath = join(root, 'llms.json');
if (!existsSync(sourcePath)) {
	console.error(`Missing ${sourcePath}. Set OPENEHR_RUST=/path/to/openehr-rust`);
	process.exit(1);
}

const doc = JSON.parse(await readFile(sourcePath, 'utf8'));
const blobPrefix = `${REPOSITORIES.core}/blob/main/`;

// The six engine crates plus the two libraries -- the same set
// sync-content.mjs publishes a page for, under the same names.
const CRATE_PAGES = new Set([
	'openehr',
	'openehr-store',
	'openehr-sqlite',
	'openehr-postgresql',
	'openehr-mysql',
	'openehr-mariadb',
	'openehr-mssql',
	'openehr-oracle'
]);

/**
 * The vendored content path a repository-relative path became, if this site
 * publishes a page for it -- the same mapping `sync-content.mjs` encodes as
 * copy operations, read here in the other direction. `null` for anything
 * this site does not vendor, which is most of the repository: root
 * documents, `agents/`, the skill folders, `spec/` and `spec/databases/` at
 * the repository root (only `openehr/spec/*.md` is published, as
 * `/spec/<page>/`).
 */
function contentPathFor(repoPath) {
	if (CRATE_PAGES.has(repoPath)) return `crates/${repoPath}.md`;
	const spec = /^openehr\/spec\/([\w.-]+\.md)$/.exec(repoPath);
	if (spec) return `spec/${spec[1]}`;
	return null;
}

let rewritten = 0;
let keptAsGithub = 0;

function resolveLink(entry) {
	if (!entry.url.startsWith(blobPrefix)) {
		// Not a repository blob link (the site's own homepage, an external
		// site) -- carried through unchanged.
		return entry;
	}
	const repoPath = entry.url.slice(blobPrefix.length);
	const contentPath = contentPathFor(repoPath);
	const route = contentPath ? routeFor(contentPath) : null;
	if (route === null) {
		keptAsGithub += 1;
		return entry;
	}
	rewritten += 1;
	return { ...entry, url: `${SITE_URL}${route}` };
}

const sections = doc.sections.map((section) => ({
	...section,
	links: section.links.map(resolveLink)
}));

const siteDoc = { ...doc, sections };

function renderTxt(d) {
	const lines = [`# ${d.name}`, '', `> ${d.summary}`, '', d.trademark_notice, '', d.independence];
	for (const section of d.sections) {
		lines.push('', `## ${section.title}`, '');
		for (const entry of section.links) {
			lines.push(`- [${entry.title}](${entry.url}): ${entry.description}`);
		}
	}
	lines.push('');
	return lines.join('\n');
}

const staticDir = join(siteRoot, 'static');
await mkdir(staticDir, { recursive: true });
await writeFile(join(staticDir, 'llms.txt'), renderTxt(siteDoc));
await writeFile(join(staticDir, 'llms.json'), `${JSON.stringify(siteDoc, null, 2)}\n`);

console.log(
	`Synced llms.txt/llms.json from ${sourcePath}: ${rewritten} links rewritten to ${SITE_URL}, ` +
		`${keptAsGithub} kept as GitHub links (not published here).`
);
